create index p2o_sg_identity_geom_gix on p2o_sg_identity using gist (geom);
create index p2o_sg_identity_class_bix on p2o_sg_identity (feature_class, feature_id);
analyze p2o_sg_identity;

do $validation$
declare
  invalid_count integer;
  interior_count integer;
  boundary_count integer;
  safe_distance double precision;
begin
  select count(*) into invalid_count from p2o_sg_identity
  where public.st_srid(geom) <> 4326 or public.st_isempty(geom) or not public.st_isvalid(geom) or public.st_dimension(geom) <> 2;
  if invalid_count <> 0 then raise exception 'P2O_FULL_GEOMETRY_VALIDITY_FAILURE:%', invalid_count; end if;
  select count(*) into interior_count from p2o_sg_identity
  where feature_class in ('building','building_part')
    and geom && public.st_setsrid(public.st_point(103.8601839,1.2826713),4326)
    and public.st_covers(geom, public.st_setsrid(public.st_point(103.8601839,1.2826713),4326));
  if interior_count <> 2 then raise exception 'P2O_INTERIOR_CANDIDATE_COUNT_FAILURE:%', interior_count; end if;
  select count(*) into boundary_count from p2o_sg_identity
  where feature_class in ('building','building_part')
    and geom && public.st_setsrid(public.st_point(103.8605263,1.2827539),4326)
    and public.st_covers(geom, public.st_setsrid(public.st_point(103.8605263,1.2827539),4326));
  if boundary_count <> 1 then raise exception 'P2O_BOUNDARY_CANDIDATE_COUNT_FAILURE:%', boundary_count; end if;
  select public.st_distance(
    public.st_transform(public.st_setsrid(public.st_point(103.8601839,1.2826713),4326),32648),
    public.st_boundary(public.st_transform(public.st_makeenvelope(103.855,1.278,103.868,1.289,4326),32648))
  ) into safe_distance;
  if safe_distance < 400 then raise exception 'P2O_BBOX_CONTAINMENT_RADIUS_FAILURE:%', safe_distance; end if;
end
$validation$;

set local enable_seqscan = off;
explain (analyze, buffers, format json)
select feature_id from p2o_sg_identity
where feature_class in ('building','building_part')
  and geom && public.st_setsrid(public.st_point(103.8601839,1.2826713),4326)
  and public.st_covers(geom, public.st_setsrid(public.st_point(103.8601839,1.2826713),4326))
order by feature_id;

select json_build_object(
  'case_id','P2O-SG-MARINA-BAY-001',
  'source_snapshot_id','p2o-sg-marina-bay-osm-20260831t211331z-v1',
  'identity_feature_count',(select count(*) from p2o_sg_identity),
  'valid_geometry_count',(select count(*) from p2o_sg_identity where public.st_isvalid(geom)),
  'invalid_geometry_count',(select count(*) from p2o_sg_identity where not public.st_isvalid(geom)),
  'interior_candidate_count',(select count(*) from p2o_sg_identity where feature_class in ('building','building_part') and public.st_covers(geom,public.st_setsrid(public.st_point(103.8601839,1.2826713),4326))),
  'boundary_candidate_count',(select count(*) from p2o_sg_identity where feature_class in ('building','building_part') and public.st_covers(geom,public.st_setsrid(public.st_point(103.8605263,1.2827539),4326))),
  'boundary_touch_count',(select count(*) from p2o_sg_identity where feature_class in ('building','building_part') and public.st_touches(geom,public.st_setsrid(public.st_point(103.8605263,1.2827539),4326))),
  'metric_srid',32648,
  'anchor_to_coverage_boundary_m',public.st_distance(
    public.st_transform(public.st_setsrid(public.st_point(103.8601839,1.2826713),4326),32648),
    public.st_boundary(public.st_transform(public.st_makeenvelope(103.855,1.278,103.868,1.289,4326),32648))
  ),
  'max_radius_contained_within_query_bbox_gate_m',400,
  'context_completeness_at_contained_radius','UNKNOWN',
  'default_800m_complete',false,
  'temporary_only',true
) as validation_result;

rollback;
